class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {num: 1 for num in arr}  # Each number can form a tree by itself

        for i, num in enumerate(arr):
            for j in range(i):
                if num % arr[j] == 0:  # arr[j] is a factor of num
