using namespace std;

int maximumWithdrawal(vector<int>& nums) {
    stack<pair<int, int>> st;
    int answer = 0;

    for (int i = nums.size() - 1; i >= 0; i--) {
        while (!st.empty() && nums[i] < st.top().first) {
            answer = max(answer, st.top().second - i);
            st.pop();
        }
        if (!st.empty()) {
            answer = max(answer, st.top().second - i);
        }
        st.push({nums[i], i});
    }

    return answer;
}

