#include <iostream>

int minOperationsToZero(int n) {
    int answer = 0, flag = 0;
    for (int i = 31; i >= 0; i--) {
        if ((n >> i) & 1) {
            if (flag == 0) {
                answer++;
                flag = 1;
            } else {
                answer--;
            }
        } else {
            flag = 0;
        }
    }
    return answer;
}

