public String reverseString(String s, int k) {
    char[] c = s.toCharArray();
    for (int i = 0; i < s.length(); i += 2 * k) {
        int start = i;
        int end = Math.min(i + k - 1, s.length() - 1);
        while (start < end) {
            char temp = c[start];
            c[start] = c[end];
            c[end] = temp;
            start++;
            end--;
        }
    }
    return new String(c);
}
