typedef long long ll;

int countSpecialSubsequences(vector<int>& nums) {
    ll zeros = 0, ones = 0, twos = 0;
    const int mod = 1e9 + 7;

    for (int i = 0; i < nums.size(); i++) {
        if (nums[i] == 0) {
            zeros = (2 * zeros + 1) % mod;
        } else if (nums[i] == 1) {
            ones = (ones * 2 + zeros) % mod;
        } else if (nums[i] == 2) {
            twos = (twos * 2 + ones) % mod;
        }
    }

    return twos;
}
