function alternateIncreasingDecreasingString(s) {
    let output = [];
    let charCount = new Array(26).fill(0);

    for (let i = 0; i < s.length; i++) {
        let charIndex = s.charCodeAt(i) - 97;
        charCount[charIndex]++;
    }

    let count = s.length;
    while (count > 0) {
        for (let i = 0; i < charCount.length; i++) {
            if (charCount[i] > 0) {
                output.push(String.fromCharCode(i + 97));
                charCount[i]--;
                count--;
            }
        }

        for (let i = charCount.length - 1; i >= 0; i--) {
            if (charCount[i] > 0) {
                output.push(String.fromCharCode(i + 97));
                charCount[i]--;
                count--;
            }
        }
    }

    return output.join('');
}

