#include <vector>
#include <unordered_map>

int longestArithmeticSequence(std::vector<int>& nums) {
    std::unordered_map<int, int> diffMap;
    int maxLength = 0;

    for (int i = 0; i < nums.size(); ++i) {
        for (int j = 0; j < i; ++j) {
            int diff = nums[i] - nums[j];
            diffMap[diff] = std::max(diffMap[diff], diffMap[diff] + 1);
            maxLength = std::max(maxLength, diffMap[diff]);
