#include <vector>

int countServers(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();

    std::vector<int> rowFreq(m, 0);
    std::vector<int> colFreq(n, 0);

    // Update frequency vectors
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                rowFreq[i]++;
                colFreq[j]++;
            }
        }
    }

    int totalServers = 0;

    // Check communication state
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1 && (rowFreq[i] > 1 || colFreq[j] > 1)) {
                totalServers++;
            }
        }
    }

    return totalServers;
}

