class Solution:
    def findMinStep(self, board: str, hand: str) -> int:
        from collections import Counter

        def clean(board):
            stack = []
            for ball in board:
                if stack and stack[-1][0] != ball and stack[-1][1] >= 3:
                    stack.pop()
                if not stack or stack[-1][0] != ball:
                    stack.append([ball, 1])
                else:
                    stack[-1][1] += 1
            if stack and stack[-1][1] >= 3:
                stack.pop()
            return ''.join(ball * count for ball, count in stack)

        def dfs(board, hand_counter):
            if not board:
                return 0
            res, i = float("inf"), 0
            while i < len(board):
                j = i + 1
                while j < len(board) and board[i] == board[j]:
                    j += 1
                incr = 3 - (j - i)
                if hand_counter[board[i]] >= incr:
                    incr = 0 if incr < 0 else incr
                    hand_counter[board[i]] -= incr
                    temp = dfs(clean(board[:i] + board[j:]), hand_counter)
                    if temp >= 0:
                        res = min(res, temp + incr)
                    hand_counter[board[i]] += incr
                i = j
            return res if res != float("inf") else -1

        return dfs(board, Counter(hand))
```

This solution uses a depth-first search (DFS) approach combined with a helper function `clean` to remove groups of three or more consecutive balls of the same color. The `dfs` function explores all possible ways to insert balls from the hand into the board and keeps track of the minimum number of balls needed to clear the board. The `Counter` from the `collections` module is used to efficiently manage the count of balls in the hand.

