#include <iostream>
#include <string>
#include <unordered_set>

bool isPathCrossing(std::string path) {
    int x = 0, y = 0;
    std::unordered_set<std::string> visited;
    visited.insert("0,0");

    for (char c : path) {
        if (c == 'E') x++;
        else if (c == 'W') x--;
        else if (c == 'N') y++;
        else if (c == 'S') y--;

        std::string current = std::to_string(x) + "," + std::to_string(y);
        if (visited.count(current)) return true;
        visited.insert(current);
    }

    return false;
}

int main() {
    std::string inputPath = "NESW"; // Example input path
    if (isPathCrossing(inputPath)) {
        std::cout << "Path crosses itself at some point.\n";
    } else {
        std::cout << "Path does not cross itself.\n";
    }

    return 0;
}
