#include <unordered_map>
#include <vector>

int findShortestSubArray(std::vector<int>& nums) {
    int minimumLength = nums.size();
    int maximumFrequency = 0;

    std::unordered_map<int, int> frequencyMap;
    std::unordered_map<int, int> first;

    for (int i = 0; i < nums.size(); i++) {
        if (first.find(nums[i]) == first.end()) {
            first[nums[i]] = i;
            frequencyMap[nums[i]] = 1;
        } else {
            frequencyMap[nums[i]]++;
        }

        int degree = frequencyMap[nums[i]];

        if (degree > maximumFrequency) {
            maximumFrequency = degree;
            minimumLength = i - first[nums[i]] + 1;
        } else if (degree == maximumFrequency) {
            minimumLength = std::min(minimumLength, i - first[nums[i]] + 1);
        }
    }

    return minimumLength;
}
