### Step 4: Java Code Implementation
```java
public class Solution {
    int[][][] dp;

    public int solveBoxes(int[] boxes) {
        dp = new int[boxes.length][boxes.length][boxes.length];
        return calculatePoints(boxes, 0, boxes.length - 1, 0);
    }

    private int calculatePoints(int[] boxes, int l, int r, int k) {
        if (l > r) return 0;
        if (dp[l][r][k] != 0) return dp[l][r][k];

        while (r > l && boxes[r] == boxes[r - 1]) {
            r--;
            k++;
        }

        int points = calculatePoints(boxes, l, r - 1, 0) + (k + 1) * (k + 1);

        for (int i = l; i < r; i++) {
            if (boxes[i] == boxes[r]) {
                points = Math.max(points, calculatePoints(boxes, l, i, k + 1) + calculatePoints(boxes, i + 1, r - 1, 0));
            }
        }

        dp[l][r][k] = points;
        return points;
    }
}
```

