        def backtrack(pos, used):
            if pos == n + 1:
                return 1
            count = 0
            for i in range(1, n + 1):
                if not used[i] and (pos % i == 0 or i % pos == 0):
                    used[i] = True
                    count += backtrack(pos + 1, used)
                    used[i] = False
            return count

