```java
public int[] decompressRLElist(int[] nums) {
    int length = 0;
    for (int i = 0; i < nums.length; i += 2) {
        length += nums[i];
    }

    int[] result = new int[length];
    int startIdx = 0;
    for (int i = 0; i < nums.length; i += 2) {
        Arrays.fill(result, startIdx, startIdx + nums[i], nums[i + 1]);
        startIdx += nums[i];
    }

    return result;
}
