# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def reverseOddLevels(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root:
            return root

        # Queue for level order traversal
        queue = deque([root])
        level = 0

        while queue:
            level_size = len(queue)
            nodes_to_reverse = []

            for _ in range(level_size):
                node = queue.popleft()

                if level % 2 == 1:
                    nodes_to_reverse.append(node)

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            # Reverse the node values at the current odd level
            if level % 2 == 1:
                for i in range(len(nodes_to_reverse) // 2):
                    nodes_to_reverse[i].val, nodes_to_reverse[~i].val = nodes_to_reverse[~i].val, nodes_to_reverse[i].val

            level += 1

        return root
