### Step 3: Implementation in Java
```java
public class JobAssignment {
    int minTime = Integer.MAX_VALUE;

    public int minTimeToFinish(int[] jobs, int k) {
        int[] workers = new int[k];
        assignJobs(jobs, workers, 0, 0);
        return minTime;
    }

    private void assignJobs(int[] jobs, int[] workers, int index, int maxTime) {
        if (index == jobs.length) {
            minTime = Math.min(minTime, maxTime);
            return;
        }

        for (int i = 0; i < workers.length; i++) {
            workers[i] += jobs[index];
            assignJobs(jobs, workers, index + 1, Math.max(maxTime, workers[i]));
            workers[i] -= jobs[index];
            if (workers[i] == 0) break; // Avoid unnecessary work
        }
    }

    public static void main(String[] args) {
        int[] jobs = {1, 2, 8, 1, 2, 8, 4, 7};
        int k = 2;
        JobAssignment assignment = new JobAssignment();
        int maxWorkingTime = assignment.minTimeToFinish(jobs, k);
        System.out.println("Maximum working time: " + maxWorkingTime);
    }
}
```

