// Java implementation of the algorithm
public int[] assignFlowerTypes(int n, int[][] paths) {
    Map<Integer, Set<Integer>> graph = new HashMap<>();
    for (int[] path : paths) {
        graph.computeIfAbsent(path[0], k -> new HashSet<>()).add(path[1]);
        graph.computeIfAbsent(path[1], k -> new HashSet<>()).add(path[0]);
    }

    int[] result = new int[n];
    for (int i = 0; i < n; i++) {
        Set<Integer> colorsUsed = new HashSet<>();
        for (int neighbor : graph.getOrDefault(i, Collections.emptySet())) {
            colorsUsed.add(result[neighbor]);
        }
        for (int color = 1; color <= 4; color++) {
            if (!colorsUsed.contains(color)) {
                result[i] = color;
                break;
            }
        }
    }
    return result;
}
