public int findLargestIndex(int[] nums) {
    int max = Integer.MIN_VALUE;
    int secondMax = Integer.MIN_VALUE;
    int maxIndex = -1;

    for (int i = 0; i < nums.length; i++) {
        if (nums[i] > max) {
            secondMax = max;
            max = nums[i];
            maxIndex = i;
        } else if (nums[i] > secondMax) {
            secondMax = nums[i];
        }
    }

    if (secondMax * 2 <= max) {
        return maxIndex;
    } else {
        return -1;
    }
}
