import java.util.HashMap;
import java.util.Map;

public class SubsequenceCounter {
    public static void main(String[] args) {
        // Test the code with provided examples
        String[] words1 = {"a", "b", "b", "a", "c", "d", "ac"};
        String s1 = "abcde";
        System.out.println(countSubsequences(words1, s1)); // Output: 3

        String[] words2 = {"a", "b", "b", "a", "c", "d"};
        String s2 = "abcde";
        System.out.println(countSubsequences(words2, s2)); // Output: 2
    }

    public static int countSubsequences(String[] words, String s) {
        int counter = 0;
        Map<String, Integer> wordOccurrences = new HashMap<>();

        for (String word : words) {
            wordOccurrences.put(word, wordOccurrences.getOrDefault(word, 0) + 1);
        }

        for (Map.Entry<String, Integer> entry : wordOccurrences.entrySet()) {
            counter += checkSubsequence(entry.getKey(), s) * entry.getValue();
        }

        return counter;
    }

    public static int checkSubsequence(String word, String s) {
        int count = 0;
        int i = 0, j = 0;

        while (i < word.length() && j < s.length()) {
            if (word.charAt(i) == s.charAt(j)) {
                i++;
            }
            j++;
        }

        if (i == word.length()) {
            count++;
        }

        return count;
    }
}
```

