// O(n) for each check.
boolean check(double mid, int[] A, int K) {
	int n = A.length;
	int p1 = 0, q1 = 0;
	int total = 0;

	for (int i = 0, j = 0; i < n; i++) {
		for (; j < n; j++) { // j will not backtrack.
			if (i < j && A[i] < A[j] * mid) {
				if (p1 == 0 || p1 * A[j] < A[i] * q1) {
					p1 = A[i];
					q1 = A[j];
				}
				break;
			}
		}
		total += n - j;
	}
	if (total <= K) {
		if (p == 0 || p * q1 < p1 * q) {
			p = p1;
			q = q1;
		}
		return true;
	} else {
		return false;
	}
}

public int[] kthSmallestPrimeFraction(int[] A, int K) {
