	double low = 0.0;
	double high = 1.0;
	// Around 30 times of iteration
	while (high - low > 1e-8) {
		double mid = (low + high) / 2.0;
		if (check(mid, A, K)) {
			low = mid;
		} else {
			high = mid;
		}
	}
	return new int[] { p, q };
