class Solution:
    def cheapestJump(self, coins: List[int], maxJump: int) -> List[int]:
        n = len(coins)
        if coins[-1] == -1:
            return []

        # Dynamic programming arrays
        dp = [float('inf')] * n
        parent = [-1] * n
        dp[-1] = coins[-1]

