#include <iostream>
#include <string>

void reverseWord(std::string& s, int left, int right) {
    while (left < right) {
        std::swap(s[left], s[right]);
        left++;
        right--;
    }
}

std::string reverseWords(std::string s) {
    int left = 0, right = 0;
    while (left < s.length()) {
        while (right < s.length() && s[right] != ' ') {
            right++;
        }
        reverseWord(s, left, right - 1);
        left = right + 1;
        right = left;
    }
    return s;
}

int main() {
    std::string input = "this is a sample string";
    std::string reversed = reverseWords(input);
    std::cout << "Reversed string: " << reversed << std::endl;
    return 0;
}
