        dp[0] = True  # Base case: empty array is trivially partitionable

        for i in range(2, n + 1):
            # Check for the condition of two equal elements
            if i >= 2 and nums[i - 1] == nums[i - 2]:
                dp[i] = dp[i] or dp[i - 2]

