    int size = q.size();
    for (int k = 0; k < size; k++) {
        auto [x, y] = q.front();
        q.pop();
        for (auto dir : directions) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                if (grid[nx][ny] == 1) continue;
                visited[nx][ny] = 1;
                q.push({nx, ny});
            }
            if (grid[nx][ny] == 1) return steps;
        }
    }
    steps++;
}
return -1; // Island 2 not reached
