function subsetsWithDup(nums) {
    let result = [];
    nums.sort((a, b) => a - b);

    const dfs = (i, nums, slate) => {
        if (i === nums.length) {
            result.push(slate.slice());
            return;
        }

        dfs(i + 1, nums, slate); // Exclude current element

        slate.push(nums[i]);
        dfs(i + 1, nums, slate); // Include current element
        slate.pop();
    };

    dfs(0, nums, []);

    const hash = {};
    result = result.filter((subset) => {
        const key = subset.join(',');
        if (hash[key]) return false;
        hash[key] = true;
        return true;
    });

    return result;
}

