List<String> findMissingRanges(int[] nums, int lower, int upper) {
    List<String> result = new ArrayList<>();

    for (int i = 0; i <= nums.length; i++) {
        if (i == 0) {
            lower = nums[i];
        } else if (i == nums.length || nums[i] != nums[i - 1] + 1) {
            result.add(getRange(lower, nums[i] - 1));
            if (i < nums.length) {
                lower = nums[i] + 1;
            }
        }
    }

    return result;
}

private String getRange(int lower, int upper) {
    return lower == upper ? String.valueOf(lower) : lower + "->" + upper;
}
