#include <vector>
using namespace std;

int solve(int position, int pieces, vector<vector<int>>& dp) {
    if (position > end) return 0;
    if (dp[position][pieces] != -1) return dp[position][pieces];
    if (pieces == 0) return 0;

    int takeSlice = slices[position] + solve(position + 2, pieces - 1, dp);
    int leaveSlice = solve(position + 1, pieces, dp);

    dp[position][pieces] = max(takeSlice, leaveSlice);
    return dp[position][pieces];
}

int maximumSlices(vector<int>& slices) {
    int n = slices.size();
    vector<vector<int>> dp1(n, vector<int>(n / 3 + 1, -1));
    vector<vector<int>> dp2(n, vector<int>(n / 3 + 1, -1));

    int result1 = solve(0, n / 3, dp1);
    int result2 = solve(1, n / 3, dp2);

    return max(result1, result2);
}
```

