class DisjointSetUnion {
    int[] root;

    public DisjointSetUnion(int n) {
        root = new int[n];
        for (int i = 0; i < n; i++) {
            root[i] = i;
        }
    }

    public int find(int x) {
        if (root[x] != x) {
            root[x] = find(root[x]);
        }
        return root[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) {
            return;
        }
        root[rootY] = rootX;
    }
}

public int countRegions(char[][] grid) {
    int n = grid.length;
    int m = grid[0].length;
    DisjointSetUnion dsu = new DisjointSetUnion(n * m);

    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            char currentChar = grid[i][j];
            int currentPos = i * m + j;

            if (currentChar == '/' || currentChar == '\\') {
                if (j > 0 && grid[i][j - 1] == currentChar) {
                    dsu.union(currentPos, currentPos - 1);
                }
                if (i > 0 && grid[i - 1][j] == currentChar) {
                    dsu.union(currentPos, currentPos - m);
                }
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int currentPos = i * m + j;
            if (grid[i][j] == '/' || grid[i][j] == '\\') {
                int nextPos = (i + 1) * m + j + 1;
                if (grid[i][j] == grid[i + 1][j + 1]) {
                    dsu.union(currentPos, nextPos);
                }
            }
        }
    }

    for (int i = 0; i < n * m; i++) {
        if (dsu.find(i) == i) {
            count++;
        }
    }

    return count;
}
