import java.util.*;

public class CommonStringFinder {
    public String[] findCommonStrings(String[] arr1, String[] arr2) {
        Map<String, Integer> wordFrequency = new HashMap<>();
        List<String> result = new ArrayList<>();
        int minSum = Integer.MAX_VALUE;

        for (int i = 0; i < arr1.length; i++) {
            wordFrequency.put(arr1[i], wordFrequency.getOrDefault(arr1[i], 0) + i);
        }

        for (int i = 0; i < arr2.length; i++) {
            if (wordFrequency.containsKey(arr2[i])) {
                int sum = wordFrequency.get(arr2[i]) + i;
                if (sum < minSum) {
                    minSum = sum;
                    result.clear();
                    result.add(arr2[i]);
                } else if (sum == minSum) {
                    result.add(arr2[i]);
                }
            }
        }

        return result.toArray(new String[0]);
    }
}
