from typing import List
from itertools import pairwise

class Solution:
    def shortestSuperstring(self, words: List[str]) -> str:
        n = len(words)
        g = [[0] * n for _ in range(n)]
        for i, a in enumerate(words):
            for j, b in enumerate(words):
                if i != j:
                    for k in range(min(len(a), len(b)), 0, -1):
                        if a[-k:] == b[:k]:
                            g[i][j] = k
                            break
        dp = [[0] * n for _ in range(1 << n)]
        p = [[-1] * n for _ in range(1 << n)]
        for i in range(1 << n):
            for j in range(n):
                if (i >> j) & 1:
                    pi = i ^ (1 << j)
                    for k in range(n):
                        if (pi >> k) & 1:
                            v = dp[pi][k] + g[k][j]
                            if v > dp[i][j]:
                                dp[i][j] = v
                                p[i][j] = k
        j = 0
        for i in range(n):
            if dp[-1][i] > dp[-1][j]:
                j = i
        arr = [j]
        i = (1 << n) - 1
        while p[i][j] != -1:
            i, j = i ^ (1 << j), p[i][j]
            arr.append(j)
        arr = arr[::-1]
        vis = set(arr)
        arr.extend([j for j in range(n) if j not in vis])
        ans = [words[arr[0]]] + [words[j][g[i][j] :] for i, j in pairwise(arr)]
        return ''.join(ans)
```

This solution constructs the shortest superstring by first calculating the overlap between each pair of words. It then uses dynamic programming to find the optimal order of concatenation, minimizing the total length of the resulting string. The final result is constructed by following the path determined by the dynamic programming table.

## Step 1: Problem Description
Given an array of integers, find all elements that appear more than 1/3 of the time in the array.

## Step 2: Approach Explanation - Moore's Voting Algorithm
- Initialize two variables `E1` and `C1` to keep track of the first majority element and its count.
- Use Moore's Voting Algorithm to find the majority element after one iteration.
- Repeat the process to find the second majority element using variables `E2` and `C2`.
- Check if the counts of `E1` and `E2` are greater than `n/3`, where `n` is the size of the array.
- Return the elements that meet the condition.

## Step 3: Implementation
```python
def majority_elements(nums):
    E1, E2 = None, None
    C1, C2 = 0, 0

    for num in nums:
        if C1 == 0 and num != E2:
            E1 = num
        elif C2 == 0 and num != E1:
            E2 = num

        if num == E1:
            C1 += 1
        elif num == E2:
            C2 += 1
        else:
            C1 -= 1
            C2 -= 1

    C1, C2 = 0, 0
    for num in nums:
        if num == E1:
            C1 += 1
        elif num == E2:
            C2 += 1

    result = []
    if C1 > len(nums) // 3:
        result.append(E1)
    if C2 > len(nums) // 3:
        result.append(E2)

    return result
```

